corner_types = {0: 0}
for r in range(nrows - 1):
    for c in range(ncols - 1):
        if grid[r, c] == 4 and grid[r, c+1] == 4 and grid[r+1, c] == 4 and grid[r+1, c+1] == 4:
            for dr in [0, 1]:
                for dc in [0, 1]:
                    nr, nc = r + dr, c + dc
                    types = set()
                    for krr, knc in [(nr-1, nc), (nr+1, nc), (nr, nc-1), (nr, nc+1)]:
